const fs = require('node:fs')
const { createRequire } = require('node:module')
const fromVsce = createRequire(require.resolve('@vscode/vsce/package.json'))
const semver = fromVsce('semver')
const assert = require('node:assert/strict')
const source = JSON.parse(fs.readFileSync('../.trellis/tasks/09-29-harness-vsix-package/research/evidence/dependency-patch-sources.json', 'utf8'))
const lock = JSON.parse(fs.readFileSync('package-lock.json', 'utf8'))
for (const metadata of source.registry) {
  const name = metadata.name
  const version = metadata.version
  assert.equal(lock.packages['node_modules/' + name].version, version)
  assert.equal(lock.packages['node_modules/' + name].resolved, metadata.tarball)
  assert.equal(lock.packages['node_modules/' + name].integrity, metadata.integrity)
  assert.equal(JSON.parse(fs.readFileSync('node_modules/' + name + '/package.json')).version, version)
  for (const advisory of source.advisories) {
    for (const affected of advisory.vulnerabilities) {
      if (affected.package.name !== name) continue
      const range = affected.vulnerable_version_range.replaceAll(',', ' ')
      assert.equal(semver.satisfies(version, range), false, advisory.ghsa_id + ': ' + version + ' in ' + range)
    }
  }
}
assert.ok(semver.satisfies('3.1.7', lock.packages['node_modules/ajv'].dependencies['fast-uri']))
assert.ok(semver.satisfies('7.29.1', lock.packages['node_modules/cheerio'].dependencies.undici))
console.log(JSON.stringify({official_advisories_checked: source.advisories.length, installed_versions: { 'fast-uri': '3.1.7', undici: '7.29.1' }, compatible_parent_ranges: true, registry_and_lock_integrity_match: true}))
